from collections import deque
import heapq


def manhattan(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])


def neighbors(grid, cell):
    r, c = cell
    for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] != '#':
            yield (nr, nc)


def bfs(grid, start, goal):
    queue = deque([start])
    dist = {start: 0}
    while queue:
        cell = queue.popleft()
        if cell == goal:
            return dist[cell]
        for nxt in neighbors(grid, cell):
            if nxt not in dist:
                dist[nxt] = dist[cell] + 1
                queue.append(nxt)
    return -1


def astar(grid, start, goal):
    open_heap = [(manhattan(start, goal), 0, start)]
    best_g = {start: 0}
    while open_heap:
        f, g, cell = heapq.heappop(open_heap)
        if cell == goal:
            return g
        if g > best_g.get(cell, float('inf')):
            continue
        for nxt in neighbors(grid, cell):
            ng = g + 1
            if ng < best_g.get(nxt, float('inf')):
                best_g[nxt] = ng
                heapq.heappush(open_heap, (ng + manhattan(nxt, goal), ng, nxt))
    return -1

TRANSITIONS = {
    ('IDLE', 'start'): 'CLEANING',
    ('CLEANING', 'battery_low'): 'RETURNING',
    ('CLEANING', 'done'): 'RETURNING',
    ('RETURNING', 'docked'): 'CHARGING',
    ('CHARGING', 'full'): 'IDLE',
}


def next_state(state, event):
    if event == 'stop':
        return 'IDLE'
    return TRANSITIONS.get((state, event), state)


def run(events, start='IDLE'):
    state = start
    for event in events:
        state = next_state(state, event)
    return state

def reward(prev_dist, new_dist, hit_obstacle, reached_goal):
    if reached_goal:
        return 10.0
    if hit_obstacle:
        return -5.0
    return round(-0.1 + (prev_dist - new_dist), 2)

